import { defineSchema, lazySchema } from "../../schemas/index.js";
export const getCachePolicySchema = defineSchema((v) => v.enum(["no-cache", "cache", "cache-first"]));
export const getMcpConfigSchema = defineSchema((v) => v.object({
    enabled: v.boolean().optional(),
    cachePolicy: getCachePolicySchema().optional(),
}));
// Backward-compat aliases
export const cachePolicySchema = lazySchema(getCachePolicySchema);
export const McpConfigSchema = lazySchema(getMcpConfigSchema);
